export const supplementalWebEntries: JournalEntry[] = [
  make('owned-website-value', {
    slug: 'site-professionnel-reseaux-sociaux-canaux', title: 'Site professionnel, réseaux sociaux et IA : quel rôle pour chaque canal ?', description: 'Attribuer un rôle mesurable à chaque canal sans croire qu’une entreprise doit nécessairement tout posséder.',
    introduction: 'Un site, un réseau social et une réponse produite par une IA n’offrent pas la même relation au public. Les réseaux peuvent aider à faire découvrir une activité et à participer à une conversation ; un site permet de composer une information durable, structurée et reliée à une action. Les assistants de recherche peuvent encore changer la façon dont les personnes découvrent les contenus. La décision utile n’est donc pas « faut-il être partout ? », mais « quelle tâche chaque canal remplit-il, et quelle dépendance accepte-t-on ? »',
    sources: [S.helpful, S.aiSearch, S.cnil, S.labels], sections: [
      { title: 'Partir de la tâche du visiteur', paragraphs: [
        'Listez les questions fréquentes avant de choisir un canal : comprendre une offre, vérifier une adresse, comparer deux solutions, demander un devis ou suivre une actualité. Une page de service est adaptée aux réponses stables ; un réseau peut donner du contexte et permettre des échanges ; un formulaire ou un téléphone ouvre la suite. Un canal sans tâche claire risque de devenir une obligation éditoriale sans valeur évidente.',
        'Pour chaque tâche, notez l’information nécessaire, la personne qui la tient à jour et le prochain geste attendu. Un visiteur qui découvre une activité depuis une publication ne devrait pas devoir reconstituer le prix, le périmètre ou les conditions dans plusieurs fils. Le site peut alors servir de référence cohérente, tandis que la publication sociale attire l’attention et renvoie vers cette information.'
      ] },
      { title: 'Distinguer audience et maîtrise', sourceUrls: [S.helpful.url, S.aiSearch.url], paragraphs: [
        'Une plateforme offre une audience potentielle et des outils de diffusion, mais ses règles d’affichage, ses formats et ses possibilités de contact sont définis par son opérateur. Google indique pour ses expériences génératives de Search que les fondamentaux de visibilité et la publication d’informations utiles restent pertinents ; aucune technique spéciale ne garantit une présence dans une réponse générée. Cette incertitude plaide pour une information accessible au-delà d’un seul flux.',
        'Un site n’efface pas toute dépendance : il repose lui aussi sur un hébergement, un nom de domaine, des outils, des sauvegardes et du travail de mise à jour. La maîtrise signifie plutôt que l’organisation peut choisir la structure et le ton, exporter ou déplacer ses contenus avec un effort connu, et maintenir un moyen de contact. Décrivez ces coûts comme des responsabilités concrètes, pas comme une indépendance absolue.'
      ] },
      { title: 'Tracer un parcours simple', paragraphs: [
        'Dessinez une séquence courte : découverte, vérification, action, réponse. La découverte peut venir d’une recommandation, d’un moteur ou d’une plateforme sociale ; la page doit ensuite répondre à une question ; l’action doit annoncer ce qui se passera après. Cette carte révèle les canaux redondants et les transitions manquantes. Elle évite aussi de confondre portée d’une publication et demande réellement traitée.',
        'Exemple fictif : une entreprise de réparation publie des conseils locaux sur un réseau, tient sur son site ses zones d’intervention et critères de prise en charge, puis propose un appel plutôt qu’un long formulaire. Le résultat attendu de l’exercice est un parcours compréhensible et une liste de contenus à maintenir. Ce scénario ne prédit ni le nombre de demandes ni le canal qui en apportera le plus.'
      ] },
      { title: 'Réduire la dépendance sans collectionner les canaux', sourceUrls: [S.cnil.url], paragraphs: [
        'Conservez les informations qui doivent rester trouvables : coordonnées, offre actuelle, politique de confidentialité, preuves que vous êtes autorisé à publier et procédures de contact. Si une plateforme disparaît ou limite un compte, vous pourrez rediriger les personnes vers une autre voie. Cette précaution est utile, mais elle ne justifie pas de recopier sans discernement des données personnelles ou des messages privés dans un fichier maison.',
        'La CNIL rappelle, dans son contexte de réutilisation de données publiées sur Internet, que les droits des personnes et leur traitement doivent être organisés. Pour une présence commerciale, gardez une finalité claire pour les demandes reçues, limitez les champs aux informations nécessaires et indiquez comment les personnes peuvent exercer leurs droits. Les obligations exactes dépendent du traitement et de la situation ; une liste de contrôle éditoriale ne remplace pas l’analyse de conformité.'
      ] },
      { title: 'Choisir une combinaison proportionnée', checklist: [
        'Quelle tâche prioritaire chaque canal sert-il ?', 'Qui peut tenir chaque information à jour ?', 'Quelle option de contact reste utilisable si un compte est inaccessible ?', 'Les données collectées sont-elles nécessaires à la suite annoncée ?', 'Quel signal observe-t-on sans prétendre attribuer toute la demande à un seul canal ?'
      ], paragraphs: [
        'Une petite structure peut commencer par une page à jour et un canal où ses clients se trouvent déjà. Un site avec plusieurs rubriques, un CMS et des outils d’analyse n’est pas automatiquement supérieur à une page claire et un numéro de téléphone. À l’inverse, une entreprise qui a des offres, des preuves, des équipes ou des langues différentes peut avoir besoin d’une base éditoriale plus structurée.',
        'Évaluez la combinaison après une période définie avec des indicateurs simples : questions auxquelles le contenu répond, demandes correctement orientées, contenus périmés et temps consacré à la maintenance. Il s’agit de faciliter une décision, pas d’attribuer causalement une vente à chaque impression. Ajoutez un canal uniquement quand vous pouvez lui donner un propriétaire, une fonction et un mode de suivi.'
      ] }
    ], takeaway: 'Attribuez à chaque canal une tâche, un propriétaire et une prochaine action. Gardez les informations essentielles dans un espace que vous savez mettre à jour et faire évoluer, puis utilisez les plateformes selon leur apport réel à votre public.'
  }, {
    slug: 'professional-website-social-networks-channel-roles', title: 'Professional websites, social networks and AI: what role for each channel?', description: 'Give each channel a practical role without assuming every business must own every digital channel.',
    introduction: 'A website, a social network and an AI-generated answer do not create the same relationship with an audience. Social platforms can help people discover a business and join a conversation; a website can present durable, structured information tied to an action. Search assistants may further change how people find content. The useful question is not “must we be everywhere?” but “what task does each channel perform, and which dependencies are acceptable?”',
    sources: [S.helpful, S.aiSearch, S.cnil, S.labels], sections: [
      { title: 'Start with the visitor’s task', paragraphs: [
        'List common questions before choosing channels: understand an offer, check a location, compare options, request a quote or follow an update. A service page suits stable answers; a social network can provide context and conversation; a form or phone call opens the next step. A channel without a clear task can become an editorial obligation with little visible value.',
        'For each task, note the information needed, who maintains it and the next expected action. Someone who discovers a business through a post should not have to reconstruct its price, scope or conditions across several threads. The website can serve as a coherent reference while a social post attracts attention and points to that information.'
      ] },
      { title: 'Separate audience from control', sourceUrls: [S.helpful.url, S.aiSearch.url], paragraphs: [
        'A platform offers a potential audience and distribution tools, but its operator controls display rules, formats and contact options. Google says that useful information and ordinary search visibility fundamentals remain relevant to its generative Search experiences; no special technique guarantees inclusion in a generated answer. That uncertainty is one reason to keep important information available beyond a single feed.',
        'A website does not remove every dependency: it still relies on hosting, a domain, tools, backups and maintenance work. Control means an organisation can choose its structure and tone, understand the effort needed to export or move content, and maintain a way to get in touch. Describe these costs as practical responsibilities, not absolute independence.'
      ] },
      { title: 'Map a simple journey', paragraphs: [
        'Draw a short sequence: discovery, verification, action, response. Discovery may come from a recommendation, search or social platform; a page should then answer a question; the action should explain what happens next. This map exposes redundant channels and missing transitions. It also prevents reach on a post from being confused with a request that has actually been handled.',
        'Hypothetical example: a repair business shares local advice on a social network, keeps its service area and eligibility criteria on its website, and offers a phone call instead of a long form. The intended result of the exercise is a clear journey and a list of content to maintain. This scenario predicts neither request volume nor which channel will generate the most.'
      ] },
      { title: 'Reduce dependency without collecting channels', sourceUrls: [S.cnil.url], paragraphs: [
        'Keep information that must remain findable: current contact details, the offer, a privacy notice, evidence you are authorised to publish and contact procedures. If a platform disappears or limits an account, you can direct people elsewhere. This precaution does not justify copying personal data or private messages into a home-grown database without a clear reason.',
        'In its context of reusing data published on the internet, France’s CNIL highlights that people’s rights and how requests are handled need organisation. For a business presence, define why incoming requests are kept, limit fields to what the next step needs, and explain how people can exercise their rights. Exact obligations depend on the processing and circumstances; an editorial checklist is not a compliance assessment.'
      ] },
      { title: 'Choose a proportionate mix', checklist: [
        'What priority task does each channel serve?', 'Who can keep each piece of information current?', 'What contact option remains if an account becomes unavailable?', 'Is each collected data point needed for the stated next step?', 'What signal can be observed without attributing all demand to one channel?'
      ], paragraphs: [
        'A small organisation can start with one current page and a channel its customers already use. A site with many sections, a CMS and analytics tools is not automatically better than a clear page and a phone number. Conversely, an organisation with distinct offers, evidence, teams or languages may need a more structured editorial base.',
        'Review the mix after a defined period using simple indicators: questions answered, requests routed correctly, outdated content and time spent on maintenance. The point is to support a decision, not to claim causal credit for every sale. Add a channel only when you can give it an owner, a purpose and a way to review its contribution.'
      ] }
    ], takeaway: 'Give each channel a task, an owner and a next action. Keep essential information somewhere you know how to update and evolve, then use platforms according to the value they offer your audience.'
  }),
  make('headless-wordpress-tradeoffs', {
    slug: 'wordpress-headless-couts-previsualisation-exploitation', title: 'WordPress headless : quand séparer l’édition et le front vaut son coût', description: 'Évaluer aperçu, modèles de contenu, authentification et double exploitation avant de séparer WordPress du site.',
    introduction: 'Un WordPress headless conserve le CMS pour la rédaction et laisse une autre application produire l’interface publique. Cette séparation peut aider quand un front spécifique doit évoluer indépendamment, ou quand plusieurs expériences réutilisent les mêmes contenus. Elle crée aussi une intégration à maintenir : API, aperçus, médias, modèles, publication, caches et accès doivent continuer de fonctionner ensemble. Le choix ne se résume donc pas à comparer des performances de rendu. Il faut évaluer le gain produit face au coût quotidien de deux systèmes liés.',
    sources: [S.astroWp, S.astroCms, S.rest, S.auth, S.roles], sections: [
      { title: 'Vérifier que la séparation répond à un besoin réel', sourceUrls: [S.astroCms.url, S.astroWp.url], paragraphs: [
        'Listez ce qui ne fonctionne pas dans le site intégré actuel : plusieurs interfaces, exigences de présentation inhabituelles, réutilisation du contenu dans une application ou séparation nécessaire entre équipe éditoriale et déploiement. Comparez avec des solutions plus modestes : thème existant, blocs limités, modèles contrôlés ou amélioration ciblée du site. Si le seul argument est « headless est moderne », le besoin reste à prouver.',
        'Astro explique qu’un CMS peut offrir éditeur visuel et contenus structurés tout en séparant le rendu, et propose un guide d’intégration avec WordPress REST. La même documentation rappelle qu’Astro peut fonctionner avec Markdown sans CMS. Ces exemples décrivent des options techniques, pas une conclusion sur le meilleur choix d’une entreprise donnée.'
      ] },
      { title: 'Dessiner les modèles et l’expérience de prévisualisation', paragraphs: [
        'Avant de migrer, répertoriez les types de contenu, champs, taxonomies, blocs réutilisables, variantes linguistiques et relations entre pages. Demandez ensuite comment une personne verra son brouillon exactement comme le public avant publication. La prévisualisation nécessite une route protégée, un lien de retour du CMS ou un mécanisme équivalent ; elle ne découle pas automatiquement de l’existence d’une API de lecture.',
        'Exemple fictif : une équipe utilise un bloc de témoignage qui accepte un texte, un nom avec consentement et une image facultative. Le contrat de contenu devrait préciser le rendu si l’image manque, la validation du nom, les langues disponibles et le comportement de l’aperçu. Le résultat attendu est une liste de cas à réaliser avant migration, et non la supposition que le front pourra interpréter chaque bloc WordPress sans adaptation.'
      ] },
      { title: 'Contrôler les API, droits et contenus', sourceUrls: [S.rest.url, S.auth.url, S.roles.url], paragraphs: [
        'La REST API WordPress expose posts, pages et d’autres ressources ; les types personnalisés doivent être configurés pour être accessibles. L’exemple Astro utilise une lecture publique sans identifiants, ce qui évite de placer des secrets sur le front. Une opération d’écriture ou l’accès à du contenu non publié demande une authentification et des capacités adaptées ; les identifiants secrets doivent rester côté serveur.',
        'Distribuez les accès selon les actions : un éditeur de contenu n’a pas nécessairement besoin d’installer des extensions ou de modifier le thème. Les capacités du Site Editor peuvent aussi ouvrir des fonctions plus larges que la seule modification d’une page. Examinez l’API lorsque le schéma change, la pagination, les limites de requête, les erreurs et la manière de retirer un secret compromis. L’intégration doit rester fonctionnelle après une modification éditoriale ordinaire.'
      ] },
      { title: 'Estimer la double exploitation', paragraphs: [
        'Ajoutez au coût du CMS celui du front, de son hébergement ou déploiement, du cache, des notifications de reconstruction, de la surveillance et du diagnostic entre systèmes. Identifiez qui traite une publication invisible, une image manquante ou une API indisponible. Une architecture distribuée peut améliorer la flexibilité, mais il faut un propriétaire qui comprend les deux côtés et sait dans quel ordre les réparer.',
        'Le traitement des URL doit également être prévu : slugs, prévisualisations, redirections, canoniques et versions de langue. Vérifiez comment le site se reconstruit après une publication et ce qui se passe si une reconstruction échoue. Les coûts et capacités dépendent de l’architecture choisie ; ne déduisez pas un gain de performance ou de sécurité du simple fait que WordPress ne sert plus directement la page publique.'
      ] },
      { title: 'Faire un prototype avec un seuil de décision', checklist: [
        'Quel cas du site intégré actuel ne peut pas répondre au besoin ?', 'L’aperçu reproduit-il fidèlement chaque état de contenu ?', 'Quelles données sont publiques et lesquelles exigent un accès serveur ?', 'Qui surveille CMS, front, API et reconstruction ?', 'Quel coût récurrent et quel critère feraient revenir à une architecture plus simple ?'
      ], paragraphs: [
        'Prototypez un parcours représentatif plutôt qu’une page isolée : brouillon, aperçu, publication, mise à jour, réutilisation d’un bloc et retour arrière. Mesurez le temps de rédaction, le nombre d’étapes manuelles, les défauts de rendu et la facilité de correction. Un test limité révèle les dépendances ; il ne prouve pas que l’architecture résistera à toute charge ou à toutes les extensions futures.',
        'Comparez ce résultat à l’option intégrée avec les mêmes contenus et critères. Si le gain de produit ne compense pas la double exploitation, réduisez la portée ou conservez le CMS avec un front classique. Headless a du sens lorsque la séparation résout un problème réel et que l’organisation peut financer et maintenir les contrats entre systèmes.'
      ] }
    ], takeaway: 'Avant de découpler WordPress, testez un parcours éditorial complet, aperçu et publication compris. Séparez le front seulement si le bénéfice produit dépasse le coût durable d’une API, de deux exploitations et d’une responsabilité de réparation claire.'
  }, {
    slug: 'headless-wordpress-tradeoffs-preview-and-operations', title: 'Headless WordPress: when is separating editing and the front end worth the cost?', description: 'Evaluate previews, content models, authentication and dual operations before decoupling WordPress.',
    introduction: 'Headless WordPress keeps the CMS for writing and lets another application produce the public interface. The separation can help when a specialised front end needs to evolve independently or several experiences reuse the same content. It also creates an integration to maintain: API, previews, media, templates, publishing, caches and access must keep working together. The decision is not just a comparison of rendering performance. It means weighing a product benefit against the everyday cost of two connected systems.',
    sources: [S.astroWp, S.astroCms, S.rest, S.auth, S.roles], sections: [
      { title: 'Check that decoupling addresses a real need', sourceUrls: [S.astroCms.url, S.astroWp.url], paragraphs: [
        'List what does not work in the current integrated site: several interfaces, unusual presentation needs, content reuse in an application or a necessary boundary between editorial and deployment teams. Compare simpler options: an existing theme, limited blocks, controlled templates or a targeted site improvement. If the only argument is “headless is modern,” the need is still unproven.',
        'Astro explains that a CMS can provide visual editing and structured content while separating rendering, and offers a WordPress REST integration guide. The same documentation notes that Astro can work with Markdown without a CMS. These examples describe technical options, not a conclusion about the best choice for any particular business.'
      ] },
      { title: 'Design content models and preview experience', paragraphs: [
        'Before migrating, list content types, fields, taxonomies, reusable blocks, language variants and relationships between pages. Then ask how an editor sees a draft exactly as the public will before publication. Preview needs a protected route, a return link from the CMS or an equivalent mechanism; it does not follow automatically from having a read API.',
        'Hypothetical example: a team uses a testimonial block with text, a consented name and an optional image. The content contract should define rendering when the image is absent, name validation, available languages and preview behaviour. The intended outcome is a list of cases to build before migration, not an assumption that the front end can interpret every WordPress block without adaptation.'
      ] },
      { title: 'Control APIs, permissions and content', sourceUrls: [S.rest.url, S.auth.url, S.roles.url], paragraphs: [
        'The WordPress REST API exposes posts, pages and other resources; custom types must be configured to be accessible. Astro’s example uses public reads without credentials, avoiding secrets on the front end. Writing or access to unpublished content requires authentication and appropriate capabilities; secret credentials must remain server-side.',
        'Assign access by action: a content editor may not need to install plugins or change the theme. Site Editor capabilities can also open broader functionality than editing a single page. Review the API when schemas change, pagination, request limits, errors and how to revoke a compromised secret. The integration should keep working after an ordinary editorial change.'
      ] },
      { title: 'Estimate dual operations', paragraphs: [
        'Add the CMS cost to the front end, its hosting or deployment, cache, rebuild notifications, monitoring and cross-system diagnosis. Identify who handles an invisible publication, missing image or unavailable API. A distributed architecture may improve flexibility, but it needs an owner who understands both sides and knows what to repair first.',
        'Plan URL handling too: slugs, previews, redirects, canonicals and language versions. Check how the site rebuilds after publication and what happens when a rebuild fails. Costs and capabilities depend on the chosen architecture; do not infer a performance or security gain simply because WordPress no longer serves the public page directly.'
      ] },
      { title: 'Prototype with a decision threshold', checklist: [
        'Which current integrated-site case cannot meet the need?', 'Does preview faithfully reproduce each content state?', 'Which data is public and which requires server-side access?', 'Who monitors the CMS, front end, API and rebuild?', 'What recurring cost and criterion would favour returning to a simpler architecture?'
      ], paragraphs: [
        'Prototype a representative journey rather than one isolated page: draft, preview, publication, update, block reuse and rollback. Measure writing time, manual steps, rendering defects and ease of correction. A limited trial reveals dependencies; it does not prove the architecture will handle every load or future plugin.',
        'Compare the result with the integrated option using the same content and criteria. If the product benefit does not cover dual operations, reduce scope or keep the CMS with a conventional front end. Headless makes sense when separation solves a real problem and the organisation can fund and maintain contracts between systems.'
      ] }
    ], takeaway: 'Before decoupling WordPress, test a complete editorial journey including preview and publishing. Separate the front end only when the product benefit outweighs the lasting cost of an API, two operational surfaces and clear repair ownership.'
  }),
  make('seo-migration-controls', {
    slug: 'refonte-site-controles-migration-seo', title: 'Refondre un site : préparer la migration SEO et surveiller les écarts', description: 'Cartographier les anciennes adresses, vérifier les redirections et suivre les erreurs après lancement.',
    introduction: 'Une refonte peut modifier simultanément les pages, leurs adresses, les gabarits, les liens internes et les signaux transmis aux moteurs. Même si le nouveau site paraît correct, une page importante peut avoir perdu son équivalent, être bloquée ou rediriger vers une destination générique. La migration SEO réduit ces erreurs en traitant les URLs comme un inventaire à contrôler, pas comme un effet secondaire du développement. Elle ne garantit pas que le trafic restera stable : les moteurs doivent explorer et réévaluer les changements, et d’autres facteurs influencent les résultats.',
    sources: [S.migration, S.redirects, S.canonical, S.recrawl], sections: [
      { title: 'Établir un inventaire avant de changer les adresses', sourceUrls: [S.migration.url], paragraphs: [
        'Rassemblez les URLs connues depuis le site actuel, le sitemap, les données de recherche disponibles et les pages qui reçoivent encore des liens entrants. Pour chacune, notez son contenu, son utilité, ses visites ou conversions observées si ces données existent, et la décision prévue : conserver, déplacer, fusionner ou retirer. Une source unique ne révèle pas nécessairement toutes les anciennes adresses ; documentez le périmètre du relevé.',
        'Créez une table ancien URL → décision → nouvelle URL → vérification. Les pages similaires peuvent être regroupées seulement si la nouvelle destination répond vraiment à leurs besoins. Google avertit que rediriger de nombreuses anciennes URLs sans rapport vers la page d’accueil peut dérouter les visiteurs et être interprété comme une erreur douce. Une adresse supprimée sans équivalent doit recevoir une réponse cohérente, souvent un statut de disparition approprié.'
      ] },
      { title: 'Choisir et tester les redirections', sourceUrls: [S.redirects.url], paragraphs: [
        'Quand le contenu a déménagé de façon permanente, Google recommande des redirections serveur permanentes, par exemple HTTP 301 ou 308, lorsque c’est possible. Les redirections temporaires signalent une situation différente. La décision dépend de la durée prévue et de la destination véritable ; conserver la même règle sans tenir compte du contexte peut envoyer un signal erroné et ralentir les visiteurs.',
        'Testez un échantillon représentatif, puis l’ensemble automatisable, en contrôlant code de réponse, destination, boucles et chaînes inutiles. Une suite d’anciennes adresses pointant chacune vers une autre avant d’arriver à la destination complique le suivi. Les pages nouvelles doivent aussi fonctionner directement, y compris sur mobile et sans dépendre d’une redirection qui masque une URL incorrecte.'
      ] },
      { title: 'Vérifier canoniques, directives et sitemap', sourceUrls: [S.canonical.url], paragraphs: [
        'Vérifiez les liens rel="canonical", les directives robots, les liens internes, les versions de langue et le sitemap sur la version finale. Le guide Google explique que la canonicalisation s’appuie sur plusieurs signaux, notamment redirections, sitemap et annotation canonique ; la balise seule ne constitue pas un ordre garanti. Une copie de préproduction qui garde noindex ou une ancienne canonique peut empêcher la nouvelle page attendue d’être retenue.',
        'Le sitemap publié devrait contenir les URLs que l’organisation souhaite faire explorer, pas les anciennes adresses redirigées ni les pages que l’on demande de ne pas indexer. N’ajoutez pas une nouvelle structure linguistique sans vérifier les équivalences entre versions. La cohérence entre navigation, liens internes, balises et sitemap simplifie l’interprétation, même si le moteur conserve la décision finale.'
      ] },
      { title: 'Préparer un tableau de surveillance post-lancement', paragraphs: [
        'Avant le lancement, notez les nombres de référence disponibles : pages à migrer, erreurs d’exploration, pages indexées, impressions et clics par type de page. Après, suivez les réponses HTTP, les erreurs 404, les redirections, les pages demandées au moteur et les parcours commerciaux essentiels. Google recommande de surveiller Search Console et les journaux, mais les délais de recrawl varient et une demande de crawl ne garantit pas l’indexation.',
        'Exemple fictif : sur un site de 40 pages, l’équipe associe chaque adresse prioritaire à une destination, teste 10 URLs critiques avant lancement puis examine les erreurs quotidiennes la première semaine. Le résultat attendu est un registre de corrections et de responsables, pas l’absence garantie de fluctuation. La taille du site ne rend pas ces nombres représentatifs d’un autre projet.'
      ] },
      { title: 'Gérer les écarts comme des décisions', checklist: [
        'Chaque URL importante a-t-elle une destination pertinente ou une suppression expliquée ?', 'Les redirections sont-elles directes, permanentes lorsque nécessaire et sans boucle ?', 'Les nouvelles canoniques, directives et sitemaps se correspondent-ils ?', 'Qui traite une erreur et à quel rythme ?', 'Quelles données serviront à comparer avant et après sans promettre la stabilité ?'
      ], paragraphs: [
        'Les premiers jours peuvent montrer des écarts : pages encore indexées à l’ancienne adresse, liens externes non mis à jour, nouvelle URL absente du rapport ou baisse temporaire de clics. Classez-les par impact et par cause vérifiée. Une baisse isolée n’établit pas que la migration entière a échoué ; une hausse moyenne ne prouve pas non plus qu’aucune page importante n’a été perdue.',
        'Conservez les redirections assez longtemps pour que les utilisateurs et robots rencontrent la nouvelle destination, et mettez à jour vos propres liens. La recommandation Google générale est de garder ces redirections aussi longtemps que possible, généralement au moins un an. Prévoyez une revue après la phase de lancement et une autre après la stabilisation observée. Toute modification d’URL reste un changement à suivre, pas un événement qu’on clôture le jour du déploiement.'
      ] }
    ], takeaway: 'Préparez la correspondance des URLs, vérifiez les signaux techniques avant le lancement et attribuez les erreurs à une personne après. Suivez les résultats dans leur périmètre : une migration maîtrisée réduit les défauts évitables, mais ne promet pas un trafic inchangé.'
  }, {
    slug: 'website-redesign-seo-migration-checks', title: 'Website redesign: prepare SEO migration controls and monitor the gaps', description: 'Map old URLs, verify redirects and follow errors after launch.',
    introduction: 'A redesign can change pages, their addresses, templates, internal links and search signals at the same time. Even when the new site looks right, an important page may have lost its equivalent, be blocked or redirect to a generic destination. SEO migration reduces these errors by treating URLs as an inventory to control, not a development side effect. It cannot guarantee stable traffic: search engines must crawl and reassess changes, and other factors affect results.',
    sources: [S.migration, S.redirects, S.canonical, S.recrawl], sections: [
      { title: 'Build an inventory before changing addresses', sourceUrls: [S.migration.url], paragraphs: [
        'Collect known URLs from the current website, sitemap, available search data and pages that still receive inbound links. For each, note its content, usefulness, observed visits or conversions if available, and planned decision: keep, move, merge or remove. One source may not reveal every old address; document the inventory’s scope.',
        'Create a table of old URL → decision → new URL → verification. Similar pages should be consolidated only when the new destination really serves their needs. Google warns that redirecting many unrelated old URLs to a homepage can confuse visitors and may be treated as a soft error. A removed page with no equivalent needs a coherent response, often an appropriate gone status.'
      ] },
      { title: 'Choose and test redirects', sourceUrls: [S.redirects.url], paragraphs: [
        'When content has moved permanently, Google recommends permanent server-side redirects such as HTTP 301 or 308 where possible. Temporary redirects signal a different situation. The decision depends on expected duration and the genuine destination; applying the same rule without context can send the wrong signal and slow visitors.',
        'Test a representative sample and then everything that can be automated, checking response code, destination, loops and unnecessary chains. A set of old addresses that each point somewhere else before reaching the destination complicates monitoring. New pages must also work directly, including on mobile and without depending on a redirect that hides an incorrect URL.'
      ] },
      { title: 'Check canonicals, directives and sitemap', sourceUrls: [S.canonical.url], paragraphs: [
        'Check rel="canonical" links, robots directives, internal links, language versions and the sitemap on the final site. Google explains that canonicalisation uses several signals, including redirects, sitemaps and canonical annotations; the tag alone is not a guaranteed instruction. A staging copy that retains noindex or an old canonical can prevent the expected new page from being selected.',
        'The published sitemap should contain URLs the organisation wants crawled, not redirected old addresses or pages it asks not to index. Do not add a new language structure without checking equivalence between versions. Consistency across navigation, internal links, tags and sitemap makes interpretation easier, even though the engine makes the final choice.'
      ] },
      { title: 'Prepare a post-launch monitoring table', paragraphs: [
        'Before launch, record available baselines: pages to move, crawl errors, indexed pages, impressions and clicks by page type. Afterwards, monitor HTTP responses, 404 errors, redirects, pages submitted to search engines and essential commercial journeys. Google recommends monitoring Search Console and logs, but recrawl timing varies and a crawl request does not guarantee indexing.',
        'Hypothetical example: for a 40-page site, the team maps each priority address, tests 10 critical URLs before launch and reviews errors daily during the first week. The intended result is a correction log with owners, not a guarantee of no fluctuation. The site size does not make these numbers representative of another project.'
      ] },
      { title: 'Treat gaps as decisions', checklist: [
        'Does each important URL have a relevant destination or an explained removal?', 'Are redirects direct, permanent when needed and free of loops?', 'Do the new canonicals, directives and sitemaps agree?', 'Who handles an error and how quickly?', 'What data will be compared before and after without promising stability?'
      ], paragraphs: [
        'Early days may show gaps: old addresses still indexed, external links not updated, new URLs missing from a report or a temporary click decline. Rank issues by impact and verified cause. One decline does not establish that the whole migration failed; an average increase does not prove that no important page was lost.',
        'Keep redirects long enough for users and crawlers to encounter the new destination, and update your own links. Google’s general recommendation is to keep them as long as possible, usually at least a year. Plan a review after launch and another after observed stabilisation. An address change remains something to monitor, not an event that is finished on deployment day.'
      ] }
    ], takeaway: 'Prepare the URL mapping, verify technical signals before launch and assign post-launch errors to an owner. Track results within their scope: a controlled migration reduces avoidable defects but does not promise unchanged traffic.'
  }),
  make('website-commercial-workflow', {
    slug: 'site-web-formulaire-suivi-demande-commerciale', title: 'Faire du site un outil commercial : du formulaire au suivi de la demande', description: 'Concevoir une demande accessible et proportionnée, puis rendre son traitement visible et fiable.',
    introduction: 'Un formulaire de contact ne termine pas le parcours commercial : il déclenche un travail. Il faut recevoir la demande, l’attribuer, répondre, enregistrer la suite utile et expliquer ce qui se passe si le bon interlocuteur est absent. Ajouter des champs peut sembler aider à qualifier un prospect, mais chaque donnée demandée ajoute un effort et une responsabilité de traitement. Une conception efficace relie la question posée, la capacité de suivi et le niveau de détail vraiment nécessaire. Aucun formulaire, à lui seul, ne permet de promettre plus de ventes.',
    sources: [S.labels, S.errors, S.wcag, S.cnil], sections: [
      { title: 'Dessiner la suite avant de rédiger les champs', paragraphs: [
        'Décrivez d’abord ce que l’équipe fera après réception : rappel, réponse écrite, rendez-vous ou transfert vers un service. Le formulaire ne devrait demander que les informations nécessaires à ce geste. Si la demande contient plusieurs sujets, précisez comment elle sera orientée et qui corrige une mauvaise attribution. Les champs « au cas où » augmentent la friction sans rendre la suite plus claire.',
        'Exemple fictif : un studio de rénovation propose trois choix — type de pièce, code postal et préférence de contact — puis un champ libre facultatif. Son équipe ne demande pas le budget détaillé au premier échange parce qu’elle n’en a pas besoin pour rappeler. Le résultat attendu est une première demande suffisamment contextualisée et une règle de réponse annoncée, pas une estimation de conversion.'
      ] },
      { title: 'Rendre les contrôles compréhensibles et accessibles', sourceUrls: [S.labels.url, S.wcag.url], paragraphs: [
        'Le tutoriel W3C sur les formulaires recommande d’associer des libellés aux champs afin que les personnes comprennent leur rôle et que les technologies d’assistance puissent annoncer correctement le contrôle. Indiquez les champs obligatoires, formats attendus et raisons d’une demande sensible avant que la personne les saisisse. Le critère WCAG 3.3.2 porte sur la disponibilité de libellés ou d’instructions pour les entrées.',
        'Gardez une navigation utilisable au clavier, un ordre prévisible et des messages lisibles sur mobile. Si une erreur est détectée, WCAG 3.3.1 demande d’identifier l’élément et de décrire l’erreur en texte. Évitez un état qui ne change qu’en rouge ou un message générique « invalide ». Après envoi, confirmez que la demande est partie et dites quel délai ou canal de suivi est prévu, sans annoncer de délai que l’équipe ne peut tenir.'
      ] },
      { title: 'Proportionner la qualification', paragraphs: [
        'Choisissez les informations qui modifient réellement la réponse : lieu d’intervention, famille de besoin, période souhaitée ou méthode de contact. Les détails qui servent uniquement à alimenter un outil d’analyse ou un profil futur doivent être justifiés séparément. Une liste déroulante trop longue, un téléphone obligatoire ou un consentement groupé peuvent exclure des personnes qui auraient pu recevoir une réponse simple.',
        'Distinguez aussi une demande de contact d’une inscription à une lettre d’information ou d’une demande de devis. Chaque finalité devrait être expliquée de façon compréhensible, et les options facultatives devraient rester réellement facultatives. Les choix dépendent de la situation et des règles applicables ; faire ajouter une case à cocher ne rend pas automatiquement un traitement conforme.'
      ] },
      { title: 'Organiser la réception et le suivi', sourceUrls: [S.cnil.url], paragraphs: [
        'Attribuez les demandes à une file ou une personne, définissez une solution de remplacement en cas d’absence et indiquez comment enregistrer une réponse ou une relance. La CNIL, dans le contexte des droits sur les données réutilisées, souligne l’importance d’une procédure interne pour traiter et suivre les demandes. Cette leçon organisationnelle peut inspirer un registre, mais les règles précises pour les prospects et leur durée de conservation dépendent du traitement.',
        'Exemple fictif de routine : chaque matin, une personne vérifie les demandes non attribuées ; à la clôture, les requêtes sans réponse ont une échéance et un remplaçant. Le résultat attendu est qu’aucune entrée ne reste sans propriétaire, et non une réponse dans un délai universel. Mesurez les retards à partir de votre engagement réel et documentez une procédure de correction ou de suppression.'
      ] },
      { title: 'Vérifier le parcours de bout en bout', checklist: [
        'Chaque champ est-il utile à une action clairement décrite ?', 'Les libellés et erreurs sont-ils compréhensibles sans couleur ?', 'Le clavier permet-il de remplir et envoyer le formulaire ?', 'Qui reçoit, attribue et traite la demande si le titulaire est absent ?', 'Quel signal confirme l’envoi et permet de corriger un échec ?'
      ], paragraphs: [
        'Testez une soumission valide, un champ manquant, une adresse mal formée, une pièce jointe refusée et l’indisponibilité du destinataire. Utilisez une boîte de test et des données fictives ; le test vérifie le parcours, pas les performances commerciales. Demandez aussi à une personne qui ne connaît pas la page d’expliquer les champs et le message de confirmation. Si elle ne sait pas ce qui se passe ensuite, le texte du parcours mérite d’être repris.',
        'Après quelques semaines, examinez les demandes incomplètes, doublons, retards et informations inutilisées. Retirez un champ lorsque personne ne s’en sert, ou corrigez l’attribution si les demandes sont souvent mal dirigées. Les indicateurs guident une amélioration du processus ; ils n’isolent pas l’effet du site sur le chiffre d’affaires sans protocole approprié.'
      ] }
    ], takeaway: 'Concevez d’abord la réception et la réponse, puis demandez seulement ce qui est utile. Vérifiez les libellés, les erreurs, les confirmations et les responsabilités avant de juger le formulaire sur un volume de contacts.'
  }, {
    slug: 'website-commercial-workflow-from-form-to-follow-up', title: 'Turn a website into a commercial workflow: from form to request follow-up', description: 'Design an accessible, proportionate enquiry path and make its handling reliable and visible.',
    introduction: 'A contact form does not finish the sales journey; it starts work. Someone must receive the request, assign it, reply, record useful next steps and explain what happens if the right person is away. Extra fields may seem useful for qualifying a prospect, but each requested data point adds effort and processing responsibility. Good design connects the question being asked, the team’s follow-up capacity and the detail actually needed. No form, by itself, guarantees more sales.',
    sources: [S.labels, S.errors, S.wcag, S.cnil], sections: [
      { title: 'Design the follow-up before the fields', paragraphs: [
        'First describe what the team will do after receipt: call back, reply in writing, book an appointment or transfer the request. The form should ask only for information needed for that action. If a request can concern several topics, say how it will be routed and who corrects a misassignment. “Just in case” fields add friction without clarifying what happens next.',
        'Hypothetical example: a renovation studio offers three choices—room type, postal code and preferred contact method—plus an optional free-text field. It does not ask for a detailed budget on first contact because the team does not need it to call back. The intended result is an initial request with enough context and an announced reply process, not a conversion forecast.'
      ] },
      { title: 'Make controls understandable and accessible', sourceUrls: [S.labels.url, S.wcag.url], paragraphs: [
        'W3C’s forms tutorial recommends associating labels with fields so people understand their purpose and assistive technologies can announce the control correctly. Explain required fields, expected formats and reasons for sensitive requests before someone enters them. WCAG criterion 3.3.2 concerns making labels or instructions available for inputs.',
        'Keep keyboard navigation usable, order predictable and messages readable on mobile. If an error is detected, WCAG 3.3.1 calls for identifying the item and describing the error in text. Avoid a state that changes only to red or a generic “invalid” message. After submission, confirm the request was sent and explain the expected response time or channel without promising a timeframe the team cannot meet.'
      ] },
      { title: 'Keep qualification proportionate', paragraphs: [
        'Choose information that genuinely changes the response: service location, need category, preferred date or contact method. Details collected only for analytics or a future profile need separate justification. A long dropdown, required phone number or bundled consent can exclude people who could have received a simple answer.',
        'Also distinguish a contact request from a newsletter subscription or a quote request. Each purpose should be explained clearly, and optional choices should remain optional in practice. Decisions depend on the situation and applicable rules; adding a checkbox does not automatically make processing compliant.'
      ] },
      { title: 'Organise receipt and follow-up', sourceUrls: [S.cnil.url], paragraphs: [
        'Assign requests to a queue or person, define a fallback when someone is absent and decide how to record a reply or follow-up. In its context of data subject rights for reused data, France’s CNIL highlights the value of an internal procedure to handle and track requests. This organisational lesson may inform a log, but precise rules for leads and retention periods depend on the processing.',
        'Hypothetical routine: each morning, one person checks unassigned requests; at closing, unanswered items have a due date and a backup owner. The intended result is that every entry has an owner, not a universal response time. Measure delays against your actual commitment and document how to correct or delete a record.'
      ] },
      { title: 'Check the whole journey', checklist: [
        'Does each field support a clearly described action?', 'Are labels and errors understandable without colour?', 'Can someone complete and submit the form with a keyboard?', 'Who receives, assigns and handles a request if the owner is away?', 'What signal confirms submission and supports recovery from failure?'
      ], paragraphs: [
        'Test a valid submission, a missing field, malformed email, rejected attachment and unavailable recipient. Use a test mailbox and fictional data; this checks the journey, not commercial performance. Also ask someone unfamiliar with the page to explain the fields and confirmation. If they cannot tell what happens next, revise the journey copy.',
        'After a few weeks, review incomplete requests, duplicates, delays and unused information. Remove a field that nobody needs or fix routing if requests often go astray. These signals guide process improvement; they do not isolate the website’s effect on revenue without an appropriate method.'
      ] }
    ], takeaway: 'Design receipt and response first, then ask only for what is useful. Check labels, errors, confirmations and ownership before judging the form by its contact volume.'
  }),
  make('tool-integration-silos', {
    slug: 'outils-numeriques-silos-doubles-saisies-flux', title: 'Trop d’outils, trop de doubles saisies : réparer les échanges avant d’en ajouter', description: 'Tracer les flux et leurs erreurs avant d’acheter un nouvel outil d’intégration.',
    introduction: 'Une double saisie peut ressembler à un manque d’automatisation, mais ajouter une connexion ne suffit pas toujours à la supprimer. Deux systèmes peuvent avoir des définitions différentes d’un client, d’un statut ou d’une date ; un flux automatique peut alors propager une erreur plus vite. Avant d’ajouter un connecteur, décrivez le trajet de l’information, la responsabilité de chaque outil et la façon de détecter un écart. Cet examen permet souvent de découvrir qu’une règle de travail, un identifiant ou un responsable manque avant qu’il soit nécessaire de remplacer une application.',
    sources: [S.integration, S.rest, S.auth, S.revisions], sections: [
      { title: 'Cartographier une information de bout en bout', sourceUrls: [S.integration.url], paragraphs: [
        'Choisissez un objet concret comme une demande commerciale et dessinez où il naît, qui le modifie, quel outil en est la référence et où il est recopié. Notez l’événement qui déclenche le transfert, la direction, la fréquence, le délai acceptable et la personne qui remarque une panne. Microsoft Learn recommande précisément d’examiner formats, disponibilité, déclencheurs, erreurs, direction du flux et protection des services dans le choix d’un modèle d’intégration.',
        'N’inventoriez pas seulement les applications officiellement approuvées. Demandez aux personnes de montrer les feuilles de calcul, boîtes partagées et notes locales qui permettent actuellement de terminer le travail. Une représentation honnête peut expliquer pourquoi l’équipe a gardé une saisie manuelle : l’outil cible ne permet peut-être pas une correction, une recherche ou une étape d’exception suffisamment fiable.'
      ] },
      { title: 'Définir une source de vérité et une identité commune', paragraphs: [
        'Décidez quel système fait autorité pour chaque champ, pas seulement quel produit est « le CRM ». Le calendrier peut détenir l’heure du rendez-vous, le système de facturation l’adresse de facture et la fiche client un identifiant stable. Écrivez les règles de création, fusion, correction et suppression ; sinon, un échange bidirectionnel peut créer des mises à jour concurrentes impossibles à arbitrer.',
        'Exemple fictif : deux demandes portent le même nom d’entreprise mais des adresses électroniques différentes. Un connecteur fondé seulement sur le nom peut les fusionner à tort ou en créer deux. L’exercice attendu consiste à choisir une clé fiable, définir le traitement des doublons et prévoir une file de revue. Il ne suppose pas que le logiciel concerné sait déjà effectuer ces opérations.'
      ] },
      { title: 'Prévoir répétition, retard et échec', paragraphs: [
        'Les appels réseau peuvent échouer, arriver plusieurs fois ou être traités dans un ordre différent. Une intégration doit indiquer si une répétition est sans effet, comment l’état est rapproché et qui reçoit une alerte. La documentation Microsoft présente l’idempotence et les messages hors ordre parmi les éléments à considérer ; le besoin précis dépend du type de transaction et des garanties de chaque système.',
        'Écrivez un scénario d’incident avant de choisir la technologie : l’enregistrement est-il relancé, placé en attente ou annulé ? Peut-on reprendre sans ressaisir ? Quelle trace permet de prouver ce qui a été reçu ? Les alertes doivent désigner quelqu’un et un prochain geste. Un flux qui échoue silencieusement transforme une économie de saisie en risque de données divergentes.'
      ] },
      { title: 'Limiter les accès et rendre la connexion révocable', sourceUrls: [S.rest.url, S.auth.url], paragraphs: [
        'Une intégration qui lit des contenus publics n’a pas nécessairement besoin du droit de modifier l’ensemble du site. L’API REST WordPress expose des ressources distinctes et applique des contrôles de capacité aux actions authentifiées. Les identifiants d’application WordPress sont révocables et sont conçus pour l’accès programmatique via HTTPS ; n’utilisez pas le compte personnel d’un employé sans comprendre sa portée.',
        'Créez un compte ou une identité dédiée avec les droits minimums, gardez les secrets hors du code partagé, documentez le propriétaire et définissez comment couper l’accès. Testez l’intégration avec des données fictives ou autorisées, notamment les refus, modifications et suppressions. Une connexion technique réussie ne garantit pas que le flux respecte les exigences de confidentialité ou de conservation qui s’appliquent à l’entreprise.'
      ] },
      { title: 'N’ajouter l’outil qu’après avoir établi le besoin', checklist: [
        'Quelle information circule et où fait-elle autorité ?', 'Quel identifiant relie les enregistrements sans ambiguïté ?', 'Quels doublons, retards et échecs doivent être traités ?', 'Qui voit l’erreur et peut reprendre le flux ?', 'Peut-on couper l’accès et revenir à une procédure manuelle temporaire ?'
      ], paragraphs: [
        'Comparez ensuite les options : réduire le nombre d’étapes, utiliser une fonctionnalité déjà présente, importer régulièrement un fichier contrôlé ou développer une intégration. Classez-les par fraîcheur nécessaire, volume, coût de maintenance, risque d’erreur et capacité de diagnostic. La synchronisation temps réel est inutile si une mise à jour quotidienne suffit, mais un retard trop long peut aussi gêner une opération urgente.',
        'Après mise en service, comparez périodiquement des échantillons des systèmes et mesurez les erreurs non résolues, reprises manuelles et délais. Si le processus change, revoyez le contrat du flux et son responsable. Une intégration est un système qui exige supervision et retrait ; son succès ne se mesure pas seulement à l’absence de saisie visible.'
      ] }
    ], takeaway: 'Définissez l’objet, sa source de vérité, son identifiant, les erreurs possibles et le responsable de reprise avant de choisir un connecteur. Une intégration fiable peut réduire une double saisie ; une intégration mal définie automatise surtout l’incohérence.'
  }, {
    slug: 'too-many-tools-fix-data-flows-before-adding-more', title: 'Too many tools and duplicate entry: repair the handoffs before adding another', description: 'Trace data flows and failure handling before buying another integration tool.',
    introduction: 'Duplicate entry can look like a lack of automation, but adding a connection does not always remove it. Two systems may define a customer, status or date differently; an automatic flow can then spread an error faster. Before adding a connector, describe the information’s path, each tool’s responsibility and how an inconsistency is detected. This often reveals a missing work rule, identifier or owner before any application needs replacing.',
    sources: [S.integration, S.rest, S.auth, S.revisions], sections: [
      { title: 'Map one item end to end', sourceUrls: [S.integration.url], paragraphs: [
        'Choose a concrete object such as a sales request and draw where it starts, who changes it, which tool is authoritative and where it is copied. Note the event that triggers transfer, direction, frequency, acceptable delay and who notices a failure. Microsoft Learn specifically recommends considering formats, availability, triggers, errors, flow direction and service protection when choosing an integration pattern.',
        'Do not inventory only officially approved applications. Ask people to show the spreadsheets, shared inboxes and local notes they rely on to finish work. An honest map may explain why a manual entry remains: the destination tool may not support a correction, lookup or exception step reliably enough.'
      ] },
      { title: 'Choose a source of truth and shared identity', paragraphs: [
        'Decide which system is authoritative for each field, not just which product is “the CRM.” A calendar may own the appointment time, billing the invoice address and a customer record a stable identifier. Write rules for creation, merging, correction and deletion; otherwise, a two-way exchange can produce concurrent updates that nobody can resolve.',
        'Hypothetical example: two requests have the same company name but different email addresses. A connector matching only on name could merge them incorrectly or create two records. The exercise is to choose a reliable key, define duplicate handling and plan a review queue. It does not assume the software already supports these operations.'
      ] },
      { title: 'Plan for repetition, delay and failure', paragraphs: [
        'Network calls can fail, arrive more than once or be processed out of order. An integration should state whether a retry is harmless, how state is reconciled and who receives an alert. Microsoft’s guidance lists idempotency and out-of-order messages as things to consider; the exact need depends on the transaction and each system’s guarantees.',
        'Write an incident scenario before choosing the technology: is the record retried, queued or cancelled? Can work resume without re-entry? Which trace proves what was received? Alerts need an owner and next action. A flow that fails silently turns saved typing into a risk of divergent data.'
      ] },
      { title: 'Limit access and make connections revocable', sourceUrls: [S.rest.url, S.auth.url], paragraphs: [
        'An integration that reads public content does not necessarily need permission to change the whole site. The WordPress REST API exposes distinct resources and applies capability checks to authenticated actions. WordPress application passwords can be revoked and are designed for programmatic access over HTTPS; do not use an employee’s personal account without understanding its reach.',
        'Create a dedicated account or identity with minimum permissions, keep secrets out of shared code, document the owner and define how access is removed. Test the integration with fictional or authorised data, including denied actions, updates and deletions. A successful technical connection does not establish that data flows meet the business’s applicable privacy or retention requirements.'
      ] },
      { title: 'Add tooling only after establishing the need', checklist: [
        'What information moves, and where is it authoritative?', 'Which identifier links records unambiguously?', 'Which duplicates, delays and failures need handling?', 'Who sees an error and can resume the flow?', 'Can access be revoked and a temporary manual process used?'
      ], paragraphs: [
        'Then compare options: remove a step, use a built-in feature, import a controlled file periodically or build an integration. Rate them by required freshness, volume, maintenance cost, error risk and diagnosability. Real-time synchronisation is unnecessary if a daily update is sufficient, although a long delay can still disrupt urgent work.',
        'After launch, periodically compare samples across systems and track unresolved errors, manual recovery and delay. If the process changes, review the flow contract and its owner. An integration is a system that needs monitoring and retirement; success is not measured only by the disappearance of visible typing.'
      ] }
    ], takeaway: 'Define the object, source of truth, identifier, failure cases and recovery owner before choosing a connector. A reliable integration can reduce duplicate entry; a poorly defined one mostly automates inconsistency.'
  }),
  make('small-business-digital-audit', {
    slug: 'audit-numerique-pme-decisions-priorites', title: 'Un audit numérique de PME qui débouche sur des décisions', description: 'Relier pages, outils, données et parcours à trois actions prioritaires et vérifiables.',
    introduction: 'Un audit numérique n’a de valeur que s’il aide une petite entreprise à décider quoi faire ensuite. Une longue liste d’outils, de scores automatiques et de défauts mineurs peut donner une impression de précision tout en laissant le dirigeant sans ordre de marche. Un audit proportionné décrit le périmètre, observe quelques parcours importants, distingue risque et inconfort, puis transforme les constats en actions attribuées. La démarche ci-dessous est une méthode de tri à adapter ; elle ne remplace ni une évaluation de sécurité ni un audit légal ou d’accessibilité.',
    sources: [S.crawlers, S.easyChecks, S.cnil, S.labels], sections: [
      { title: 'Fixer la question et le périmètre', paragraphs: [
        'Avant d’inspecter les outils, demandez quelle décision bloque : simplifier une demande de devis, choisir une plateforme, clarifier la responsabilité d’une donnée ou réduire une tâche manuelle. Délimitez les systèmes et les personnes concernés, puis notez ce qui est exclu. Sans ce cadrage, une revue de PME peut se transformer en inventaire interminable de toutes les applications qu’elle a jamais essayées.',
        'Choisissez ensuite trois à cinq parcours liés à l’activité : découvrir l’offre, contacter l’entreprise, recevoir une demande, établir un suivi et mettre à jour une information. Demandez à la personne qui effectue réellement chaque étape de la décrire. Une procédure théorique peut différer des échanges par courriel, feuilles de calcul et messages qui composent le travail quotidien.'
      ] },
      { title: 'Observer les parcours et leur accessibilité', sourceUrls: [S.easyChecks.url, S.labels.url], paragraphs: [
        'Pour chaque parcours, consignez les étapes, les données demandées, les changements de canal et les retours d’erreur. Les vérifications initiales de la WAI couvrent notamment titres, textes alternatifs, contraste, clavier, libellés et formulaires. Elles permettent de repérer des problèmes évidents, mais ne certifient pas le site et ne remplacent pas les critères applicables ou des tests avec des personnes handicapées.',
        'Exemple fictif : dans une entreprise imaginaire de plomberie, une demande arrive par le site, une photo est envoyée par SMS et un rendez-vous est reporté dans un calendrier personnel. L’audit note trois transmissions et le risque qu’une demande ne soit pas rappelée. Il propose d’abord un registre simple des demandes et un responsable de suivi ; aucun incident n’est affirmé comme ayant eu lieu.'
      ] },
      { title: 'Cartographier données, outils et responsabilités', sourceUrls: [S.cnil.url], paragraphs: [
        'Pour chaque information utile, notez sa source de vérité, qui la modifie, où elle est copiée et combien de temps elle reste nécessaire. Ajoutez les prestataires qui la traitent et les accès qui permettent de la consulter. L’objectif est de détecter les doublons et les responsabilités floues, pas de centraliser toutes les informations dans un nouvel outil par réflexe.',
        'La CNIL décrit, dans ses recommandations sur la réutilisation de données publiées, l’importance de traiter les droits des personnes de façon organisée. Dans un audit commercial, cela invite à identifier les formulaires, les finalités annoncées, les durées prévues et la personne qui sait répondre aux demandes. Cette grille n’établit pas la conformité d’un traitement : les obligations dépendent du cas et demandent une analyse compétente.'
      ] },
      { title: 'Classer par conséquence, fréquence et effort', paragraphs: [
        'Attribuez à chaque constat une conséquence possible, la fréquence d’exposition, la capacité de détecter une erreur et l’effort de correction. Décrivez le risque avec un scénario concret : « la demande sans téléphone ne peut pas être rappelée » est plus utile que « formulaire à moderniser ». Distinguez un dommage probable, une gêne récurrente et une préférence esthétique afin de ne pas confondre urgence et visibilité.',
        'Utilisez une grille qualitative faible, moyenne ou forte, puis discutez les désaccords. N’additionnez pas ces catégories pour produire un faux score scientifique. Une priorité forte peut venir d’un problème fréquent et simple à corriger ou d’un risque moins fréquent mais grave, à condition d’expliquer le raisonnement et la personne qui accepte le risque résiduel.'
      ] },
      { title: 'Terminer par trois décisions concrètes', checklist: [
        'Quel constat touche un parcours essentiel ?', 'Quelle action possède un responsable et une échéance réaliste ?', 'Quelle donnée ou étape sera supprimée plutôt qu’ajoutée ?', 'Quelle preuve montrera que la correction est faite ?', 'Quel sujet nécessite une expertise spécialisée avant décision ?'
      ], paragraphs: [
        'Une fiche de sortie peut contenir trois priorités, leur propriétaire, leur coût approximatif, une dépendance et le résultat observable. Ajoutez une liste d’actions différées pour les sujets qui ont besoin d’un devis ou d’un avis spécialisé. Une prochaine revue est utile si elle a une date et une question, par exemple vérifier si les demandes sont bien transmises après une modification du formulaire.',
        'Le premier livrable de l’audit peut être de ne pas acheter de nouvel outil. Remplacer une double saisie par une règle de nommage, attribuer les accès existants ou supprimer une page périmée peut être plus utile qu’un projet d’intégration. Une bonne revue respecte la capacité de l’équipe : les recommandations sans propriétaire, budget ou critère de fin sont des idées, pas un plan de décision.'
      ] }
    ], takeaway: 'Limitez l’audit à quelques parcours, attribuez les constats et terminez par trois actions ordonnées. Signalez ce que les observations ne prouvent pas et demandez une expertise lorsque la sécurité, le droit ou l’accessibilité l’exige.'
  }, {
    slug: 'small-business-digital-audit-that-drives-decisions', title: 'A small-business digital audit that leads to decisions', description: 'Connect pages, tools, data and journeys to three verifiable actions.',
    introduction: 'A digital audit is valuable only if it helps a small business decide what to do next. A long list of tools, automated scores and minor defects can feel precise while leaving the owner without an order of work. A proportionate audit sets scope, observes a few important journeys, separates risk from inconvenience and turns findings into assigned actions. The method below is a triage approach to adapt; it is not a security review or a legal or accessibility audit.',
    sources: [S.crawlers, S.easyChecks, S.cnil, S.labels], sections: [
      { title: 'Set the question and scope', paragraphs: [
        'Before inspecting tools, ask which decision is blocked: simplify a quote request, choose a platform, clarify responsibility for data or reduce manual work. Define the systems and people involved, then record what is excluded. Without this boundary, a small-business review can become a never-ending inventory of every application the company ever tried.',
        'Choose three to five journeys tied to the business: discover the offer, contact the company, receive a request, follow up and update information. Ask the person who actually performs each step to describe it. A formal procedure may differ from the emails, spreadsheets and messages that make up daily work.'
      ] },
      { title: 'Observe journeys and accessibility', sourceUrls: [S.easyChecks.url, S.labels.url], paragraphs: [
        'For each journey, record steps, requested data, channel changes and error feedback. WAI’s preliminary checks cover headings, alternative text, contrast, keyboard access, labels and forms. They help find obvious issues, but they do not certify a website or replace applicable criteria or tests with disabled people.',
        'Hypothetical example: at an imaginary plumbing company, a request arrives through the website, a photo comes by text message and an appointment is copied into a personal calendar. The audit records three handoffs and the risk that a request might not receive a call back. It first proposes a simple request log and an owner for follow-up; it does not claim an incident occurred.'
      ] },
      { title: 'Map data, tools and ownership', sourceUrls: [S.cnil.url], paragraphs: [
        'For each useful piece of information, note its source of truth, who changes it, where it is copied and how long it remains necessary. Add which vendors process it and which accounts can access it. The point is to identify duplication and unclear ownership, not to centralise all information in a new tool by reflex.',
        'In its recommendations on reusing published data, France’s CNIL describes the importance of organising responses to people’s rights. In a commercial audit, that is a prompt to identify forms, stated purposes, planned retention and the person who knows how to answer requests. This grid does not establish compliance: obligations depend on the case and require a competent analysis.'
      ] },
      { title: 'Rank by consequence, frequency and effort', paragraphs: [
        'Assign each finding a possible consequence, exposure frequency, ability to detect an error and correction effort. Describe risk through a concrete scenario: “a request without a phone number cannot be called back” is more useful than “modernise the form.” Distinguish likely harm, recurring friction and visual preference so urgency is not confused with visibility.',
        'Use a qualitative low, medium or high grid, then discuss disagreements. Do not add these categories into a false scientific score. A high priority might be a frequent, easy fix or a less frequent but serious risk, provided the reasoning and person accepting residual risk are clear.'
      ] },
      { title: 'Finish with three concrete decisions', checklist: [
        'Which finding affects an essential journey?', 'Which action has an owner and realistic deadline?', 'Which data or step can be removed instead of added?', 'What evidence will show that the fix is complete?', 'Which topic needs specialist input before a decision?'
      ], paragraphs: [
        'A close-out sheet can hold three priorities, their owner, rough cost, a dependency and an observable result. Add deferred actions that need a quote or specialist view. A follow-up review is useful when it has a date and a question, such as whether requests still reach the right person after a form change.',
        'The first outcome of an audit may be not buying another tool. Replacing duplicate entry with a naming rule, assigning existing access or removing an outdated page may be more useful than an integration project. A sound review respects the team’s capacity: recommendations with no owner, budget or completion criterion are ideas, not a decision plan.'
      ] }
    ], takeaway: 'Limit the audit to a few journeys, assign the findings and finish with three ranked actions. State what observations do not prove, and seek specialist advice when security, law or accessibility requires it.'
  }),
  make('content-automation-editorial', {
    slug: 'automatiser-production-contenu-ligne-editoriale', title: 'Automatiser la production de contenu sans perdre la ligne éditoriale', description: 'Automatiser la préparation et la vérification sans laisser un outil publier des textes sans apport.',
    introduction: 'Les outils d’automatisation peuvent accélérer la collecte de notes, le formatage ou la distribution d’un contenu. Ils ne décident pas à eux seuls si un sujet mérite d’être publié, si une affirmation est exacte ou si le texte aide réellement le public. Quand une équipe confond vitesse de génération et valeur éditoriale, elle peut produire plus de pages qui se ressemblent et demandent ensuite du travail de correction. Une chaîne saine distingue les tâches mécaniques des décisions éditoriales et rend visible qui accepte la version finale.',
    sources: [S.helpful, S.aiSearch, S.revisions, S.roles], sections: [
      { title: 'Cadrer un besoin avant d’automatiser', paragraphs: [
        'Commencez par une demande de contenu qui peut être évaluée : à qui s’adresse-t-elle, à quelle question répond-elle et quelle action de lecture suit ? Ajoutez l’expertise ou l’accès à une source qui rend la publication possible. Si le brief ne contient qu’un mot-clé et un nombre de pages à produire, l’automatisation aura peu de critères pour différencier une réponse nécessaire d’une répétition de ce qui existe.',
        'Transformez les règles de ligne éditoriale en questions concrètes. Le texte distingue-t-il fait, interprétation et conseil ? Les personnes nommées ont-elles validé l’usage de leurs propos ? Les conditions et limites sont-elles décrites ? Une grille courte est plus facile à appliquer qu’une promesse abstraite de « qualité ». Elle aide aussi à repérer les demandes auxquelles il faut répondre par une recherche ou un refus de publier.'
      ] },
      { title: 'Automatiser l’assistance, pas l’autorité', sourceUrls: [S.helpful.url, S.aiSearch.url], paragraphs: [
        'Un outil peut proposer un plan depuis un brief, repérer des liens manquants, normaliser des métadonnées ou préparer un brouillon à partir de notes autorisées. Chaque sortie reste une proposition. Google encourage les créateurs à apporter de l’information originale et de la valeur, et son guide sur les fonctionnalités génératives rappelle les principes fondamentaux de contenu utile ; produire à grande échelle sans soin ne constitue pas en soi une stratégie de visibilité.',
        'Attribuez la validation à une personne compétente sur le sujet et identifiable dans le processus. Elle doit pouvoir ouvrir les sources, vérifier la date, corriger le sens et faire arrêter la publication. Si un outil résume un document inaccessible ou invente une référence, la bonne étape est d’obtenir une source vérifiable ou de retirer l’affirmation. Une relecture de grammaire ne contrôle pas la vérité.'
      ] },
      { title: 'Construire une chaîne avec des arrêts utiles', paragraphs: [
        'Une séquence pratique peut être : brief accepté, dossier de sources, proposition de plan, brouillon, vérification factuelle, contrôle de ton et publication. Le passage à l’étape suivante doit dépendre d’un résultat visible : sources ouvertes, question adressée, personnes concernées consultées ou format vérifié. Ces points d’arrêt évitent qu’un échec initial se propage à la mise en page et à la diffusion.',
        'Exemple fictif : pour rédiger une page expliquant les aides locales à la rénovation, l’automatisation peut créer une fiche de contrôle et remplir les champs du CMS depuis un brouillon approuvé. Un rédacteur doit confirmer le territoire, les dates, les conditions d’éligibilité et les liens officiels avant publication. Le résultat attendu est une page contrôlable avec des faits attribués, pas un article prétendument validé par le processus seul.'
      ] },
      { title: 'Contrôler versions, responsabilités et répétitions', sourceUrls: [S.revisions.url, S.roles.url], paragraphs: [
        'Gardez un historique des modifications et définissez qui peut brouillonner, approuver et publier. WordPress documente rôles, capacités et révisions, ce qui illustre la distinction entre droits éditoriaux et administration générale. La configuration réelle peut varier selon les thèmes et extensions ; testez les capacités sur les comptes utilisés plutôt que de supposer qu’un rôle standard correspond exactement à votre circuit de validation.',
        'Avant d’accepter un nouveau texte, comparez-le aux pages déjà disponibles : la question est-elle réellement distincte ? Est-ce une mise à jour d’une page existante, une fusion ou une suppression qui aiderait davantage ? L’automatisation peut signaler des titres proches ou des champs manquants, mais un humain doit décider si deux contenus répondent au même besoin. Une cadence de production ne doit pas devenir une obligation de remplir le site.'
      ] },
      { title: 'Mesurer l’utilité et savoir ralentir', checklist: [
        'Chaque article correspond-il à un besoin distinct et un propriétaire ?', 'Les affirmations importantes renvoient-elles à des sources ouvertes ?', 'Qui signe l’acceptation et peut arrêter une diffusion ?', 'Quelles corrections ont été nécessaires après génération ?', 'Quel contenu existant faut-il actualiser ou retirer avant de créer le prochain ?'
      ], paragraphs: [
        'Suivez des indicateurs proches du travail : part des brouillons acceptés après correction, erreurs factuelles repérées, délai de validation, questions résolues et contenu obsolète. Les chiffres servent à comprendre les goulots d’étranglement, non à récompenser le volume. Une baisse de temps passée sur le formatage n’est bénéfique que si la vérification, la clarté ou la production d’un apport original ne se dégrade pas.',
        'Réduisez l’automatisation si les personnes ne peuvent plus vérifier les sorties ou si le contrôle demande autant de travail que la rédaction manuelle. Certaines pages sensibles exigent une expertise et une validation spécialisée ; elles ne sont pas de bons candidats à une chaîne sans supervision. La ligne éditoriale reste une responsabilité partagée, tandis que la décision de publier appartient à une personne désignée.'
      ] }
    ], takeaway: 'Automatisez les passages répétables et rendez chaque validation attribuable. La chaîne éditoriale doit aider une équipe à produire une réponse utile, sourcée et relue ; si elle ne sait qu’augmenter le volume, elle ne remplit pas cet objectif.'
  }, {
    slug: 'automate-content-production-with-editorial-judgment', title: 'Automating content production without losing editorial judgment', description: 'Automate preparation and checks while keeping unsupported, low-value copy from being published.',
    introduction: 'Automation tools can speed up collecting notes, formatting or distributing a piece. They do not decide by themselves whether a topic should be published, a claim is accurate or the text helps its audience. When a team confuses generation speed with editorial value, it may produce more pages that resemble one another and still require correction. A sound workflow separates mechanical tasks from editorial decisions and makes clear who approves the final version.',
    sources: [S.helpful, S.aiSearch, S.revisions, S.roles], sections: [
      { title: 'Define a need before automating', paragraphs: [
        'Start with a content request that can be evaluated: who is it for, what question does it answer and what reading action follows? Add the expertise or access to a source that makes publication possible. If a brief contains only a keyword and a target number of pages, automation has little basis for distinguishing a useful answer from repetition of what already exists.',
        'Turn editorial rules into concrete questions. Does the copy distinguish fact, interpretation and advice? Have named people approved use of their words? Are conditions and limitations described? A short grid is easier to apply than an abstract promise of “quality.” It also helps identify requests that need research or a decision not to publish.'
      ] },
      { title: 'Automate assistance, not authority', sourceUrls: [S.helpful.url, S.aiSearch.url], paragraphs: [
        'A tool can suggest an outline from a brief, flag missing links, standardise metadata or prepare a draft from authorised notes. Every output remains a proposal. Google encourages creators to provide original information and value, and its generative features guide points back to helpful content principles; publishing at scale without care is not, by itself, a visibility strategy.',
        'Assign approval to someone competent in the subject and visible in the process. They need to open sources, check dates, correct meaning and stop publication. If a tool summarises an inaccessible document or invents a reference, the next step is to obtain a verifiable source or remove the claim. A grammar review does not verify truth.'
      ] },
      { title: 'Build a workflow with useful stops', paragraphs: [
        'A practical sequence can be: approved brief, source pack, outline proposal, draft, fact check, tone review and publication. Moving forward should depend on visible evidence: sources opened, question addressed, affected people consulted or format checked. These checkpoints prevent an early failure from being carried into layout and distribution.',
        'Hypothetical example: to explain local home-renovation grants, automation could create a checklist and fill CMS fields from an approved draft. An editor must confirm the location, dates, eligibility conditions and official links before publication. The intended result is a verifiable page with attributed facts, not an article supposedly validated by the workflow alone.'
      ] },
      { title: 'Control versions, ownership and repetition', sourceUrls: [S.revisions.url, S.roles.url], paragraphs: [
        'Keep a revision history and define who can draft, approve and publish. WordPress documents roles, capabilities and revisions, illustrating the difference between editorial permissions and general administration. Real configurations may differ because of themes and plugins; test permissions with actual accounts instead of assuming a standard role matches the workflow exactly.',
        'Before accepting a new article, compare it with existing pages: is the question distinct? Would updating an existing page, merging or removing material help more? Automation can flag similar titles or missing fields, but a person must decide whether two pieces serve the same need. A production cadence should not become an obligation to fill the website.'
      ] },
      { title: 'Measure usefulness and know when to slow down', checklist: [
        'Does every article serve a distinct need and have an owner?', 'Do important claims point to sources that were opened?', 'Who signs off and can stop distribution?', 'What corrections were needed after generation?', 'Which existing material should be updated or removed first?'
      ], paragraphs: [
        'Track measures close to the work: drafts accepted after correction, factual errors found, review time, questions resolved and outdated content. Use numbers to understand bottlenecks, not to reward volume. Spending less time on formatting is useful only if verification, clarity and original contribution do not decline.',
        'Reduce automation if people can no longer verify its output or if review takes as much effort as writing by hand. Some sensitive pages need specialist expertise and approval; they are poor candidates for an unsupervised chain. Editorial direction remains a shared responsibility, while the decision to publish belongs to a designated person.'
      ] }
    ], takeaway: 'Automate repeatable steps and make every approval attributable. The editorial workflow should help a team create a useful, sourced and reviewed answer; if it only increases volume, it is not meeting that goal.'
  }),
  make('seo-ai-discovery', {
    slug: 'seo-recherche-ia-decouvrabilite-sans-promesse', title: 'SEO et recherche par IA : travailler la découvrabilité sans promesse magique', description: 'Consolider l’accès technique et la valeur éditoriale, puis lire les signaux de recherche avec prudence.',
    introduction: 'La recherche évolue : des résultats classiques coexistent avec des interfaces qui résument des pages ou affichent des citations. Cela ne crée pas pour autant une recette séparée qui garantit d’être cité par une IA. Pour une organisation, la découvrabilité commence par des pages que les moteurs peuvent explorer, comprendre et juger utiles, puis par une mesure réaliste de ce qui est effectivement observé. Le travail vise à rendre une information fiable et trouvable ; il ne permet pas de contrôler la sélection d’un moteur ni de prédire toutes les réponses générées.',
    sources: [S.aiSearch, S.helpful, S.crawlers, S.bingAI], sections: [
      { title: 'Commencer par l’accès et l’indexation', sourceUrls: [S.aiSearch.url, S.crawlers.url], paragraphs: [
        'Vérifiez d’abord que les pages importantes renvoient un état accessible, ne sont pas accidentellement bloquées, contiennent leur texte essentiel dans le rendu et disposent de liens internes explorables. Les sitemaps peuvent aider à découvrir des URLs, mais Google précise qu’ils ne commandent pas l’exploration ni l’indexation de chaque adresse. Une page peut être crawlée sans apparaître dans les résultats si elle n’apporte pas assez de valeur ou de demande.',
        'Séparez trois états souvent confondus : publiée, accessible au robot et présente dans les résultats. Une demande de réexploration dans Search Console n’est ni une commande d’indexation ni une garantie d’affichage. Contrôlez des exemples précis avec les outils du moteur et les journaux disponibles, puis cherchez une cause technique ou éditoriale plutôt que de soumettre la même URL encore et encore.'
      ] },
      { title: 'Écrire pour une vraie question', sourceUrls: [S.helpful.url], paragraphs: [
        'Le guide Google sur les fonctionnalités génératives renvoie aux mêmes fondamentaux de recherche et recommande une expérience utile, accessible et techniquement saine. Son guide de contenu utile invite à se demander si une page apporte une information originale ou une analyse supplémentaire plutôt que de réécrire ce qui existe déjà. Ces consignes sont des repères de l’éditeur sur ses propres systèmes, pas une formule permettant de prédire le classement.',
        'Avant de commander un article, écrivez la question du lecteur, les éléments de preuve nécessaires, l’expertise disponible et l’apport que la page peut réellement fournir. Une réponse courte, une fiche de service complète ou l’absence d’une page peut être préférable à un texte artificiellement long. Les titres descriptifs, définitions explicites et exemples aident les lecteurs à juger si la page répond à leur besoin, indépendamment de la forme du résultat de recherche.'
      ] },
      { title: 'Rendre l’information interprétable sans suroptimiser', paragraphs: [
        'Employez des termes cohérents pour désigner une activité, une personne, une offre ou un lieu. Définissez les sigles, indiquez la date lorsque la fraîcheur importe et reliez les pages connexes avec des liens compréhensibles. Les données structurées peuvent décrire un contenu lorsque le balisage correspond à ce que voit l’utilisateur, mais elles ne garantissent pas un résultat enrichi ni une citation dans une réponse générée.',
        'Évitez les pages quasi identiques créées pour multiplier les variantes de requêtes, les paragraphes ajoutés uniquement pour répéter des mots-clés et les affirmations sans origine. Une page claire peut être résumée hors de son contexte : distinguez les faits établis, les conseils et les limites. Cette précision profite au lecteur et facilite une éventuelle reprise par un moteur, sans garantir que la source sera attribuée ou sélectionnée.'
      ] },
      { title: 'Mesurer des signaux sans confondre les métriques', sourceUrls: [S.bingAI.url, S.aiSearch.url], paragraphs: [
        'Les outils ne mesurent pas tous la même chose. L’annonce de Bing Webmaster Tools décrit des vues de citations, d’URLs citées et de requêtes d’ancrage dans certaines expériences prises en charge ; Microsoft précise que le nombre de citations ne donne pas un classement ou l’importance d’une page. Il faut lire la portée de chaque métrique avant d’en faire un indicateur de performance.',
        'Tenez un journal des changements éditoriaux et techniques, puis comparez les périodes avec prudence. Les impressions, clics, pages indexées et citations répondent à des questions différentes ; un changement peut aussi coïncider avec la saison, la demande ou une mise à jour du moteur. Exemple fictif : une PME observe une baisse de clics après avoir réécrit une page. Le bon exercice consiste à vérifier sa requête, son affichage et sa réponse au besoin, non à supposer qu’un outil IA a détourné ces visiteurs.'
      ] },
      { title: 'Construire une boucle d’amélioration responsable', checklist: [
        'La page est-elle accessible et explorable ?', 'Répond-elle à une question distincte avec un apport justifiable ?', 'Les faits importants ont-ils une source et une date si nécessaire ?', 'Quelle mesure observée correspond à l’objectif choisi ?', 'Une mise à jour améliore-t-elle le lecteur même si aucune citation IA n’apparaît ?'
      ], paragraphs: [
        'Passez en revue un petit ensemble de pages prioritaires : service, tarifs ou conditions, coordonnées, réponses aux objections et contenus de référence. Corrigez d’abord les pages cassées, périmées ou redondantes. Ajoutez ensuite des éléments utiles manquants et vérifiez leur lisibilité sur mobile et avec les technologies d’assistance. Cette méthode est plus soutenable qu’un calendrier qui impose des nouveautés sans demande ni expertise disponible.',
        'La visibilité est une conséquence que les plateformes déterminent selon leurs propres systèmes. Une entreprise peut agir sur la qualité, l’accès, l’organisation et l’observation de son contenu, mais pas sur la promesse d’une citation future. Fixez donc un but contrôlable : aider une personne à comparer, trouver une information fiable ou accomplir une tâche. Le SEO aide à structurer ce travail ; il ne remplace ni l’offre ni la confiance.'
      ] }
    ], takeaway: 'Gardez les fondamentaux d’exploration et de contenu utile, mesurez chaque surface selon sa définition et n’assimilez jamais citation observée à classement. La découvrabilité se travaille ; l’inclusion dans un résultat ou une réponse reste hors de votre contrôle.'
  }, {
    slug: 'seo-ai-search-discovery-without-promises', title: 'SEO and AI search: improve discoverability without magic promises', description: 'Strengthen technical access and editorial value, then interpret search signals carefully.',
    introduction: 'Search is changing: conventional results now coexist with interfaces that summarise pages or display citations. That does not create a separate recipe that guarantees an AI will cite a site. For an organisation, discoverability starts with pages engines can crawl, understand and consider useful, followed by realistic measurement of what is actually observed. The work is to make reliable information findable; it cannot control an engine’s selection or predict every generated answer.',
    sources: [S.aiSearch, S.helpful, S.crawlers, S.bingAI], sections: [
      { title: 'Start with access and indexing', sourceUrls: [S.aiSearch.url, S.crawlers.url], paragraphs: [
        'First check that important pages return an accessible status, are not accidentally blocked, contain their essential text in the rendered output and have crawlable internal links. Sitemaps can help discovery, but Google says they do not command crawling or indexing of every address. A page may be crawled without appearing in results if it does not offer enough value or demand.',
        'Separate three states that are often confused: published, accessible to a crawler and present in results. A request to recrawl in Search Console is neither an indexing command nor a display guarantee. Check specific examples with the engine’s tools and available logs, then look for a technical or editorial cause instead of repeatedly submitting the same URL.'
      ] },
      { title: 'Write for a real question', sourceUrls: [S.helpful.url], paragraphs: [
        'Google’s guide to generative features points back to the same search fundamentals and recommends a helpful, accessible and technically sound experience. Its helpful content guide asks whether a page offers original information or further analysis instead of rewriting what is already available. These are the publisher’s principles for its own systems, not a formula that predicts rankings.',
        'Before commissioning an article, write the reader’s question, the evidence needed, available expertise and the contribution the page can actually make. A short answer, a complete service page or no new page may be better than artificially long copy. Descriptive headings, explicit definitions and examples help readers decide whether a page answers their need, whatever form the search result takes.'
      ] },
      { title: 'Make information interpretable without over-optimising', paragraphs: [
        'Use consistent terms for a business, person, offer or place. Define abbreviations, provide a date when freshness matters and link related pages with understandable text. Structured data can describe content when markup matches what users see, but it guarantees neither a rich result nor a citation in a generated answer.',
        'Avoid near-identical pages created to multiply query variants, paragraphs added only to repeat keywords and claims without provenance. A clear page can be summarised out of context: distinguish established facts, advice and limitations. This precision helps readers and makes possible reuse by an engine easier, without guaranteeing that a source will be credited or selected.'
      ] },
      { title: 'Measure signals without conflating metrics', sourceUrls: [S.bingAI.url, S.aiSearch.url], paragraphs: [
        'Tools do not all measure the same thing. Bing Webmaster Tools’ announcement describes views of citations, cited URLs and grounding queries across certain supported experiences; Microsoft says citation counts do not indicate ranking or a page’s importance. Read each metric’s scope before turning it into a performance indicator.',
        'Keep a log of editorial and technical changes, then compare periods carefully. Impressions, clicks, indexed pages and citations answer different questions; a change may also coincide with seasonality, demand or an engine update. Hypothetical example: a small business sees fewer clicks after rewriting a page. The useful exercise is to inspect its query, appearance and response to the need, not assume an AI tool diverted those visitors.'
      ] },
      { title: 'Build a responsible improvement loop', checklist: [
        'Is the page accessible and crawlable?', 'Does it answer a distinct question with a defensible contribution?', 'Do important facts have a source and, where needed, a date?', 'Which observed measure matches the chosen objective?', 'Would an update help readers even if no AI citation appears?'
      ], paragraphs: [
        'Review a small set of priority pages: services, prices or terms, contact details, objections and reference content. First fix pages that are broken, outdated or redundant. Then add missing useful material and check readability on mobile and with assistive technology. This approach is more sustainable than a calendar that demands new content without audience need or available expertise.',
        'Visibility is a consequence determined by platforms and their own systems. A business can improve content quality, access, structure and observation, but cannot promise a future citation. Set a controllable goal instead: help someone compare, find reliable information or complete a task. SEO supports that work; it does not replace the offer or trust.'
      ] }
    ], takeaway: 'Keep crawlability and useful content fundamentals, measure each surface according to its definition and never equate a citation with ranking. Discoverability can be worked on; inclusion in a result or answer remains outside your control.'
  }),
  make('redesign-business-outcomes', {
    slug: 'refonte-design-parcours-resultats-usage', title: 'Pourquoi changer le design ne suffit pas à mieux faire fonctionner un site', description: 'Relier une refonte à des tâches, des hypothèses vérifiables et des critères d’accessibilité.',
    introduction: 'Un nouveau design rend parfois un site plus actuel, mais l’apparence seule ne dit pas si une personne comprend l’offre, trouve l’information voulue ou termine une démarche. Une refonte implique des coûts de contenu, de développement, de validation et de changement des habitudes. Pour décider si elle est utile, il faut nommer le problème que le design devrait résoudre et observer des parcours concrets. Cette approche n’exige pas une étude coûteuse : elle exige d’éviter de prendre une préférence visuelle pour la preuve d’un résultat commercial.',
    sources: [S.wcag, S.labels, S.errors, S.helpful], sections: [
      { title: 'Formuler le problème avant la maquette', paragraphs: [
        'Décrivez ce qui bloque dans les termes d’un visiteur : une offre difficile à distinguer, une preuve introuvable, un formulaire qui demande trop tôt un engagement, ou une navigation qui masque une information importante. Évitez les demandes vagues comme « faire plus moderne ». Elles peuvent orienter le style, mais n’indiquent pas quel parcours doit devenir plus clair ni comment évaluer le résultat.',
        'Pour chaque problème, recueillez un exemple observable : question posée au support, page où le visiteur s’arrête, retour d’un utilisateur, champ abandonné ou contenu obsolète. Un signal isolé n’établit pas sa fréquence ni sa cause. Il fournit une hypothèse à examiner, puis à confronter à d’autres cas ou à une observation ciblée.'
      ] },
      { title: 'Relier chaque changement à une hypothèse', paragraphs: [
        'Une hypothèse utile a quatre éléments : public concerné, tâche, changement proposé et signal d’amélioration. Par exemple, « les personnes qui cherchent les horaires d’intervention les trouveront plus facilement si la zone est visible sur la page de service ». Elle n’affirme pas qu’un changement de couleur va augmenter les ventes. Elle indique ce qu’on peut regarder dans un test d’usage, une revue de contenu ou les demandes reçues.',
        'Exemple fictif : une clinique imaginaire déplace l’adresse et les conditions de rendez-vous près de l’action de réservation. Demandez à quelques personnes correspondant au public visé de trouver ces renseignements sur le prototype, puis notez où elles hésitent. Le résultat attendu est une liste de corrections et de points restés ambigus ; quelques observations ne mesurent pas l’effet de la refonte sur les consultations réelles.'
      ] },
      { title: 'Traiter l’accessibilité comme une propriété du parcours', sourceUrls: [S.wcag.url, S.labels.url, S.errors.url], paragraphs: [
        'Un parcours doit fonctionner avec différents modes d’interaction et présenter son information clairement. Les WCAG 2.2 fournissent des critères vérifiables ; le tutoriel W3C sur les formulaires explique notamment l’association entre libellé et champ. Si une erreur de saisie est détectée, la documentation d’interprétation du critère 3.3.1 précise qu’elle doit être identifiée et décrite en texte, pas seulement par une couleur.',
        'Incluez ces critères dès les premières maquettes : ordre de lecture, titres qui décrivent la section, contraste, navigation au clavier, zones cliquables, libellés visibles et messages d’erreur. Une refonte peut améliorer un défaut ou en introduire un nouveau, par exemple un contrôle stylisé difficile à nommer ou un menu qui ne se ferme pas au clavier. Une inspection automatique repère certaines choses, mais ne remplace pas l’essai du parcours par des personnes.'
      ] },
      { title: 'Séparer contenu, interface et résultat commercial', sourceUrls: [S.helpful.url], paragraphs: [
        'Un design peut rendre une information plus lisible sans que l’offre elle-même devienne plus pertinente. Google recommande de publier un contenu utile et original pour ses systèmes de recherche ; une nouvelle typographie ne transforme pas une page superficielle en réponse complète. La hiérarchie visuelle aide à comprendre, tandis que la qualité de la promesse, des preuves et des conditions relève aussi du travail éditorial et métier.',
        'Mesurez les étapes que l’équipe peut réellement observer : consultation de la page, clic vers l’action, formulaire transmis, demande correctement reçue ou tâche réalisée. Interprétez ces signaux dans leur contexte : variation saisonnière, campagne, volume faible ou changement simultané de prix peuvent les expliquer. Ne promettez pas de hausse de conversion avant d’avoir des données comparables et une méthode d’attribution crédible.'
      ] },
      { title: 'Préparer une revue de conception utile', checklist: [
        'Quel problème précis motive le changement ?', 'Quelle tâche et quel public sont concernés ?', 'Quelles informations doivent rester visibles ou faciles à retrouver ?', 'Quels critères clavier, libellés et erreurs seront examinés ?', 'Quel signal permettra de décider de conserver, modifier ou retirer la proposition ?'
      ], paragraphs: [
        'Réunissez concepteur, personne en charge du contenu, développeur et propriétaire métier autour de ces questions. La revue porte alors sur l’intention, les conséquences et les critères, et non seulement sur la palette. Repérez aussi les contenus ou parcours qui ne changent pas : une refonte intégrale peut déplacer les risques sans résoudre les difficultés prioritaires.',
        'Après mise en ligne, suivez le même parcours et la même définition des indicateurs qu’avant, dans la mesure du possible. Consignez les écarts et les explications connues, puis décidez s’il faut corriger une interface, une formulation, un processus interne ou la mesure elle-même. La bonne conclusion peut être qu’une petite modification ciblée suffit et qu’un remplacement complet du design n’est pas justifié.'
      ] }
    ], takeaway: 'Avant d’approuver une maquette, associez chaque changement à une tâche, une hypothèse et un critère accessible à vérifier. Le design améliore un parcours lorsqu’il soutient un besoin explicite ; il ne garantit pas à lui seul un résultat commercial.'
  }, {
    slug: 'redesign-beyond-appearance-user-outcomes', title: 'Why a design change alone does not make a website work better', description: 'Connect a redesign to user tasks, testable hypotheses and accessibility criteria.',
    introduction: 'A new design can make a website feel more current, but appearance alone does not tell us whether someone understands the offer, finds the needed information or completes a task. A redesign has content, development, review and habit-change costs. To decide whether it is useful, name the problem the design should solve and examine real journeys. This does not require an expensive study; it does require avoiding the assumption that visual preference proves a business outcome.',
    sources: [S.wcag, S.labels, S.errors, S.helpful], sections: [
      { title: 'Describe the problem before the mock-up', paragraphs: [
        'Describe what gets in a visitor’s way: an offer that is hard to distinguish, evidence that cannot be found, a form that asks for commitment too early, or navigation that hides important information. Avoid vague requests such as “make it more modern.” They may guide style, but do not say which journey should become clearer or how to assess the result.',
        'For each problem, collect an observable example: a support question, a page where a visitor stops, user feedback, an abandoned field or outdated copy. One signal does not establish frequency or cause. It is a hypothesis to examine and compare with other cases or a focused observation.'
      ] },
      { title: 'Connect each change to a hypothesis', paragraphs: [
        'A useful hypothesis has four elements: audience, task, proposed change and signal of improvement. For example, “people looking for service hours will find them more easily if the area is visible on the service page.” It does not claim that a new colour will raise sales. It says what could be examined in a usability session, content review or incoming requests.',
        'Hypothetical example: an imaginary clinic moves its address and appointment conditions next to the booking action. Ask a few people who match the intended audience to find the information in a prototype, then note where they hesitate. The expected output is a list of fixes and remaining ambiguities; a few observations do not measure the redesign’s effect on real appointments.'
      ] },
      { title: 'Treat accessibility as a journey property', sourceUrls: [S.wcag.url, S.labels.url, S.errors.url], paragraphs: [
        'A journey needs to work with different interaction modes and communicate information clearly. WCAG 2.2 provides testable criteria; W3C’s forms tutorial explains, among other things, how labels and fields are associated. If an input error is detected, the explanation for criterion 3.3.1 says it must be identified and described in text, not only by colour.',
        'Include these checks in early mock-ups: reading order, descriptive headings, contrast, keyboard access, click targets, visible labels and error messages. A redesign can fix a defect or introduce a new one, such as a custom control with no accessible name or a menu that cannot be closed from the keyboard. Automated checks catch some issues but do not replace trying the journey with people.'
      ] },
      { title: 'Separate content, interface and commercial outcome', sourceUrls: [S.helpful.url], paragraphs: [
        'A design can make information easier to read without making the offer more relevant. Google recommends useful, original content for its Search systems; new typography does not turn a shallow page into a complete answer. Visual hierarchy helps comprehension, while the quality of the promise, evidence and conditions also depends on editorial and business work.',
        'Measure stages the team can actually observe: page visit, click to an action, submitted form, correctly received request or completed task. Interpret signals in context: seasonality, campaign, low volume or a simultaneous price change may explain them. Do not promise a conversion lift without comparable data and a credible attribution method.'
      ] },
      { title: 'Prepare a useful design review', checklist: [
        'What specific problem motivates this change?', 'Which audience and task are affected?', 'What information must stay visible or easy to find?', 'Which keyboard, label and error criteria will be reviewed?', 'What signal will help decide whether to keep, change or remove the proposal?'
      ], paragraphs: [
        'Bring the designer, content owner, developer and business owner into the review around these questions. The discussion can then cover intent, consequences and criteria, not only the colour palette. Also identify journeys and content that are not changing: a complete redesign can move risk without addressing the highest-priority difficulties.',
        'After launch, follow the same journey and metric definitions as before, as far as possible. Record differences and known explanations, then decide whether to change an interface, wording, internal process or the measurement itself. A sound conclusion may be that a small targeted change is enough and a full visual replacement is not justified.'
      ] }
    ], takeaway: 'Before approving a mock-up, connect every change to a task, hypothesis and accessible criterion. Design improves a journey when it supports an explicit need; it does not guarantee a business outcome by itself.'
  }),
  make('wordpress-custom-nocode', {
    slug: 'wordpress-sur-mesure-nocode-exploitation-site', title: 'WordPress, sur-mesure ou no-code : comparer la capacité à exploiter son site', description: 'Choisir une solution web selon les tâches de publication, la maintenance et la sortie réellement possibles.',
    introduction: 'La comparaison entre WordPress, du développement sur mesure et une plateforme no-code tourne souvent à la bataille de préférences. Pour une entreprise, le choix a surtout des conséquences sur ce qu’elle peut publier seule, ce qu’elle devra faire maintenir, et la difficulté à reprendre ses contenus si les besoins évoluent. Une bonne décision commence par des tâches réelles et une estimation de la capacité à les tenir dans le temps. La question n’est pas de trouver une technologie qui n’a pas de contraintes, mais de choisir celles que l’équipe peut comprendre et assumer.',
    sources: [S.roles, S.revisions, S.astroCms, S.rest], sections: [
      { title: 'Décrire les tâches à réaliser', paragraphs: [
        'Écrivez les opérations d’une semaine ordinaire : modifier un horaire, publier un article, remplacer une image, créer une page de campagne, ajouter une langue ou changer un parcours. Ajoutez leur fréquence, la personne autorisée à les réaliser et le délai acceptable. Une solution qui simplifie la première publication peut compliquer le travail de routine si chaque petit changement attend un développeur.',
        'Séparez les tâches de contenu des tâches de structure. Changer un paragraphe ne devrait généralement pas exiger le même droit ou la même compétence que modifier un modèle global, une intégration ou une règle de paiement. Cette distinction permet de comparer les interfaces éditoriales, les rôles, la validation et les recours plutôt que les captures d’écran d’une démonstration commerciale.'
      ] },
      { title: 'Évaluer l’autonomie et ses garde-fous', sourceUrls: [S.roles.url, S.revisions.url], paragraphs: [
        'WordPress fournit des rôles et capacités pour différencier les actions permises ; les révisions et sauvegardes automatiques peuvent aider à récupérer certaines modifications de contenu. Ce sont des outils de travail, pas une garantie générale de sécurité ni un substitut à des sauvegardes complètes. Vérifiez quels rôles peuvent publier, gérer des extensions, modifier des gabarits ou administrer d’autres comptes dans la configuration retenue.',
        'Dans une plateforme no-code, regardez aussi qui peut publier, restaurer, exporter et inviter d’autres utilisateurs. Dans une solution sur mesure, ces fonctions sont des éléments du produit qu’il faut construire ou intégrer. Une équipe autonome ne signifie pas que tout le monde doit pouvoir tout faire : une validation éditoriale et des permissions limitées peuvent réduire les erreurs tout en laissant les mises à jour simples aux personnes concernées.'
      ] },
      { title: 'Comparer le coût de maintenance, pas le seul démarrage', paragraphs: [
        'Notez séparément l’hébergement, la licence éventuelle, les mises à jour, la surveillance, les sauvegardes, le support, les extensions et le temps interne. Une solution peu coûteuse à lancer peut devenir lourde si les mises à jour sont négligées ou si un seul prestataire connaît la structure. À l’inverse, une plateforme gérée peut réduire certaines tâches d’exploitation tout en ajoutant un abonnement, des limites ou des dépendances contractuelles.',
        'Exemple fictif : une association publie deux pages par mois et change rarement son parcours. Une autre équipe lance chaque semaine des pages localisées avec des règles propres à chaque offre. Le tableau attendu doit rendre visible que leurs besoins de validation, modèles et support diffèrent ; il ne permet pas de déclarer qu’une technologie sera la moins chère pour chacune sans chiffrer ses conditions et son travail réel.'
      ] },
      { title: 'Tester la portabilité avant de signer', sourceUrls: [S.astroCms.url, S.rest.url], paragraphs: [
        'Demandez un export représentatif, puis ouvrez-le : les titres, textes, images, identifiants, liens et métadonnées restent-ils exploitables ? Un export brut n’est pas une sortie complète si les relations entre contenus, les gabarits, les formulaires ou l’historique des adresses restent enfermés. Pour un CMS, vérifiez les formats d’export et les interfaces disponibles, ainsi que les frais ou interventions nécessaires à un transfert.',
        'Astro documente l’usage d’un CMS comme source séparée de la présentation et rappelle aussi qu’un projet peut se passer de CMS avec du Markdown. Cette flexibilité de conception ne promet pas une migration sans effort. L’architecture retenue doit prévoir les aperçus, la récupération des médias, les déclencheurs de publication et la personne qui répare un lien cassé lorsque l’API ou le format change.'
      ] },
      { title: 'Faire une décision explicable', checklist: [
        'Quelles opérations les personnes non techniques accompliront-elles sans assistance ?', 'Qui met à jour la plateforme et répond aux incidents ?', 'Quelles données, URLs et pièces jointes peut-on exporter ?', 'Quelles actions nécessitent une validation ou un droit élevé ?', 'Quelles conditions font réexaminer le choix dans un an ?'
      ], paragraphs: [
        'Donnez une note simple à chaque option sur autonomie éditoriale, souplesse de présentation, intégrations, responsabilité d’exploitation et sortie. Écrivez les preuves derrière chaque note : essai guidé, contrat, documentation ou estimation. Une grille n’est pas un score universel ; elle sert à mettre au jour les désaccords et à identifier la question qui doit être testée avant de choisir.',
        'Écartez une option si son mode de maintenance n’a pas de responsable ou si le scénario de sortie n’est pas acceptable. Vous pouvez aussi choisir une solution modeste et noter les signaux qui justifieraient une évolution : plus de contributeurs, nouveaux parcours, formats structurés ou indisponibilité répétée du support. Cette décision réversible réduit l’enjeu d’une technologie « parfaite » qui n’existe pas.'
      ] }
    ], takeaway: 'Comparez des tâches, des responsabilités et un scénario de sortie. La meilleure option est celle dont les contraintes de publication et de maintenance restent compatibles avec les personnes et le temps réellement disponibles.'
  }, {
    slug: 'wordpress-custom-code-or-no-code-operating-a-site', title: 'WordPress, custom development or no-code: compare how your business can run the site', description: 'Choose a web solution around publishing tasks, maintenance and a realistic exit path.',
    introduction: 'Comparisons between WordPress, custom development and no-code platforms often become battles of preference. For a business, the choice mostly affects what it can publish independently, what it must keep maintained and how difficult it will be to recover content as needs change. A sound decision starts with real tasks and a view of the capacity to support them over time. The question is not which technology has no constraints, but which constraints the team can understand and own.',
    sources: [S.roles, S.revisions, S.astroCms, S.rest], sections: [
      { title: 'Describe the work to be done', paragraphs: [
        'List a normal week’s operations: change opening hours, publish an article, replace an image, create a campaign page, add a language or change a journey. Add frequency, the person allowed to perform each task and an acceptable turnaround. A solution that makes the first publication easy can complicate routine work if every small change waits for a developer.',
        'Separate content tasks from structural tasks. Changing a paragraph should not usually require the same access or skill as changing a global template, an integration or a payment rule. This distinction helps compare editorial interfaces, roles, review and support rather than screenshots from a sales demonstration.'
      ] },
      { title: 'Assess autonomy and safeguards', sourceUrls: [S.roles.url, S.revisions.url], paragraphs: [
        'WordPress provides roles and capabilities to distinguish permitted actions; revisions and autosaves can help recover some content changes. These are working tools, not a general security guarantee or a replacement for full backups. Check which roles can publish, manage plugins, change templates or administer other accounts in the proposed configuration.',
        'For a no-code platform, also check who can publish, restore, export and invite users. With custom development, these features are product requirements that must be built or integrated. Team autonomy does not mean that everyone should be allowed to do everything: editorial review and limited permissions can reduce mistakes while leaving simple updates to the relevant people.'
      ] },
      { title: 'Compare maintenance, not just launch cost', paragraphs: [
        'List hosting, any license, updates, monitoring, backups, support, plugins and internal time separately. A solution that is inexpensive to launch can become burdensome if updates are neglected or only one contractor understands its structure. A managed platform can reduce some operations work while adding a subscription, limits or contractual dependencies.',
        'Hypothetical example: an association publishes two pages a month and rarely changes its journey. Another team launches localised pages every week with rules for each offer. The expected comparison should make their review, templates and support needs visible; it cannot declare which technology will cost less without pricing each team’s real conditions and work.'
      ] },
      { title: 'Test portability before signing', sourceUrls: [S.astroCms.url, S.rest.url], paragraphs: [
        'Request a representative export and open it: are titles, copy, images, identifiers, links and metadata still usable? A raw export is not a complete exit if content relationships, templates, forms or URL history remain trapped. For a CMS, check export formats and available interfaces, plus any fees or interventions required for a transfer.',
        'Astro documents using a CMS as a separate content source from presentation and also notes that a project can work without a CMS using Markdown. That design flexibility does not promise a migration without effort. The architecture still needs previews, media retrieval, publication triggers and an owner to repair a broken link when an API or format changes.'
      ] },
      { title: 'Make the decision explainable', checklist: [
        'Which tasks will non-technical contributors complete without help?', 'Who updates the platform and handles incidents?', 'Which data, URLs and attachments can be exported?', 'Which actions need review or elevated access?', 'What conditions would trigger a review of the choice in a year?'
      ], paragraphs: [
        'Give each option a simple rating for editorial autonomy, presentation flexibility, integrations, operational responsibility and exit. Record the evidence behind each rating: a guided trial, contract, documentation or estimate. A score is not universal; the grid exposes disagreements and identifies the question that should be tested before choosing.',
        'Rule out an option if nobody owns its maintenance or its exit scenario is unacceptable. You can also choose a modest solution and note signals for a future change: more contributors, new journeys, structured formats or repeated support gaps. This reversible decision lowers the stakes of finding a “perfect” technology that does not exist.'
      ] }
    ], takeaway: 'Compare tasks, responsibilities and an exit scenario. The best option is the one whose publishing and maintenance constraints fit the people and time actually available.'
  }),
];
